#!/usr/bin/env python3
"""
eVTOL Vertiport Recovery Solver
Two-stage: SCIP MIP for acceptance, constructive heuristic for scheduling.
"""
import csv, json, os, sys, math, itertools
from collections import defaultdict

# ─── Load data ───────────────────────────────────────────────────────────────
DATA = "/app/data"
def read_csv(name):
    with open(os.path.join(DATA, name), newline="") as f:
        return list(csv.DictReader(f))

with open(os.path.join(DATA, "config.json")) as f:
    CFG = json.load(f)

vertiports = {r["vertiport_id"]: r for r in read_csv("vertiports.csv")}
aircraft   = {r["aircraft_id"]: r for r in read_csv("aircraft.csv")}
routes     = {(r["origin"], r["destination"]): r for r in read_csv("routes.csv")}
requests   = {r["request_id"]: r for r in read_csv("requests.csv")}
scenarios  = {r["scenario_id"]: r for r in read_csv("scenarios.csv")}
time_slots = {int(r["slot"]): r for r in read_csv("time_slots.csv")}
grid_prices = {(r["vertiport_id"], int(r["slot"])): r for r in read_csv("grid_prices.csv")}
origin_floors = {r["origin"]: int(r["minimum_accepted_passengers"]) for r in read_csv("origin_service_floors.csv")}
groups = defaultdict(list)
group_spread = {}
for r in read_csv("request_groups.csv"):
    groups[r["group_id"]].append(r["request_id"])
    group_spread[r["group_id"]] = int(r["max_departure_spread_slots"])

sra = {}  # scenario route availability
for r in read_csv("scenario_route_availability.csv"):
    sra[(r["scenario_id"], r["origin"], r["destination"])] = r
saa = {}  # scenario aircraft availability
for r in read_csv("scenario_aircraft_availability.csv"):
    saa[(r["scenario_id"], r["aircraft_id"])] = r
service_windows = defaultdict(list)
for r in read_csv("aircraft_service_windows.csv"):
    service_windows[(r["scenario_id"], r["aircraft_id"])].append(r)
reserves = defaultdict(list)
for r in read_csv("emergency_reserve_requirements.csv"):
    reserves[(r["scenario_id"], r["vertiport_id"])].append(r)
corridor_ctrl = defaultdict(list)
for r in read_csv("corridor_slot_controls.csv"):
    corridor_ctrl[(r["scenario_id"], r["corridor_id"])].append(r)

HORIZON = CFG["planning_horizon_slots"]
RESERVE_SOC = CFG["reserve_soc_kwh"]
HIGH_SOC_FRAC = CFG["high_soc_threshold_fraction"]
TAPER_FRAC = CFG["taper_charge_fraction"]
CHARGE_EFF = CFG["charge_efficiency"]
DELAY_PEN = CFG["delay_penalty_per_passenger_slot"]
REPOS_COST = CFG["reposition_cost_per_kwh"]
TOL = CFG["quantity_tolerance"]

# ─── First-stage MIP ─────────────────────────────────────────────────────────
from pyscipopt import Model, quicksum

def solve_first_stage():
    model = Model("first_stage")
    model.setParam("gaprel", 0.0005)
    tl = 300.0
    env = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env:
        try: tl = min(tl, float(env))
        except: pass
    model.setParam("limits/time", tl)

    x = {}
    for rid, r in requests.items():
        x[rid] = model.addVar(name=f"x_{rid}", vtype="B", lb=0, ub=1, obj=0.0)

    # Group all-or-none
    for gid, members in groups.items():
        if len(members) > 1:
            for m in members[1:]:
                model.addCons(x[m] == x[members[0]], name=f"grp_{gid}_{m}")

    total_pax = sum(int(r["passengers"]) for r in requests.values())
    med_pax = sum(int(r["passengers"]) for r in requests.values() if r["priority_class"] == "medical")
    apx_pax = sum(int(r["passengers"]) for r in requests.values() if r["market"] == "airport")

    # Min accepted passenger fraction
    model.addCons(
        quicksum(int(requests[rid]["passengers"]) * x[rid] for rid in requests)
        >= CFG["minimum_accepted_passenger_fraction"] * total_pax,
        name="min_pax_frac")
    # Medical fraction
    model.addCons(
        quicksum(int(requests[rid]["passengers"]) * x[rid] for rid in requests if requests[rid]["priority_class"] == "medical")
        >= CFG["minimum_medical_accepted_fraction"] * med_pax,
        name="min_med_frac")
    # Airport market floor
    model.addCons(
        quicksum(int(requests[rid]["passengers"]) * x[rid] for rid in requests if requests[rid]["market"] == "airport")
        >= CFG["minimum_airport_accepted_passengers"],
        name="min_apx_pax")
    # Priority decline limit
    model.addCons(
        quicksum(1 - x[rid] for rid in requests if requests[rid]["priority_class"] in ("airport", "medical"))
        <= CFG["maximum_declined_priority_requests"],
        name="max_decl_priority")
    # Origin floors
    for orig, floor in origin_floors.items():
        model.addCons(
            quicksum(int(requests[rid]["passengers"]) * x[rid] for rid in requests if requests[rid]["origin"] == orig)
            >= floor,
            name=f"origin_floor_{orig}")

    # Objective: max expected fare - decline penalty
    obj_terms = []
    for rid, r in requests.items():
        fare = int(r["passengers"]) * float(r["fare_per_passenger"])
        dp = float(r["decline_penalty"])
        obj_terms.append((fare - dp) * x[rid] + dp)
    model.setObjective(quicksum(obj_terms), sense="maximize")

    model.optimize()
    status = model.getStatus()
    print(f"First-stage status: {status}")
    if status not in ("optimal", "timelimit", "gap"):
        print("WARNING: first stage not optimal")
    accepted = set()
    for rid in requests:
        if model.getVal(x[rid]) > 0.5:
            accepted.add(rid)
    print(f"Accepted {len(accepted)} of {len(requests)} requests")
    return accepted, model

# ─── Second-stage heuristic ──────────────────────────────────────────────────
def route_open(s, o, d):
    key = (s, o, d)
    if key not in sra: return False
    return sra[key]["open"] == "1" or sra[key]["open"] == "1.0" or sra[key]["open"] == 1

def route_dur(s, o, d):
    r = routes[(o, d)]
    mult = float(sra[(s, o, d)]["flight_slot_multiplier"])
    gd = int(scenarios[s]["global_delay_slots"])
    return math.ceil(int(r["flight_slots"]) * mult) + gd

def route_energy(s, o, d):
    r = routes[(o, d)]
    mult = float(sra[(s, o, d)]["energy_multiplier"])
    return float(r["energy_kwh"]) * mult

def route_noise(s, o, d, a):
    r = routes[(o, d)]
    return float(r["noise_points"]) * float(aircraft[a]["noise_class"])

def corridor_cap(s, c, slot):
    r = routes  # need any route on corridor c
    # find capacity from any route on this corridor
    for (o, d), rr in routes.items():
        if rr["corridor_id"] == c:
            cap = int(rr["corridor_capacity_per_slot"])
            break
    else:
        cap = 2
    for ctrl in corridor_ctrl.get((s, c), []):
        if int(ctrl["start_slot"]) <= slot < int(ctrl["end_slot"]):
            cap = min(cap, int(ctrl["max_flights_per_slot"]))
    return cap

def grid_limit(s, v, slot):
    gp = grid_prices.get((v, slot), {"grid_limit_multiplier": "1.0"})
    base = float(vertiports[v]["grid_kw_limit"])
    mult = float(gp["grid_limit_multiplier"])
    cd = float(scenarios[s]["charger_derate"])
    return base * mult * cd

def slot_period(slot):
    return time_slots[slot]["period"] if slot in time_slots else "day"

def schedule_scenario(s, accepted):
    """Construct a feasible schedule for scenario s serving all accepted requests."""
    # State per aircraft
    ac = list(aircraft.keys())
    loc = {}
    soc = {}
    for a in ac:
        sa = saa.get((s, a), {"release_slot": "0", "soc_derate": "1.0"})
        loc[a] = aircraft[a]["home_vertiport"]
        base_soc = float(aircraft[a]["initial_soc_kwh"]) * float(sa["soc_derate"]) * float(scenarios[s]["soc_derate"])
        soc[a] = min(base_soc, float(aircraft[a]["battery_capacity_kwh"]))

    # Service windows: aircraft must be idle at specified vertiport
    sw = {}  # (a, slot) -> (vertiport, min_soc)
    for a in ac:
        for w in service_windows.get((s, a), []):
            vs, ve = int(w["start_slot"]), int(w["end_slot"])
            ms = float(w["min_soc_kwh"])
            vp = w["vertiport_id"]
            for sl in range(vs, ve):
                sw[(a, sl)] = (vp, ms)

    # Track resource usage per slot
    pad_use = defaultdict(int)       # (v, slot) -> count
    charger_use = defaultdict(int)   # (v, slot) -> count
    grid_use = defaultdict(float)    # (v, slot) -> kW
    corridor_use = defaultdict(int)  # (c, slot) -> count
    noise_use = defaultdict(float)   # (v, slot) -> points

    # Aircraft busy intervals: list of (start, end) per aircraft
    busy = {a: [] for a in ac}

    def is_free(a, t_start, t_end):
        for (bs, be) in busy[a]:
            if t_start < be and bs < t_end:
                return False
        return True

    def add_busy(a, t_start, t_end):
        busy[a].append((t_start, t_end))
        busy[a].sort()

    def check_service_window(a, t_start, t_end, v_from, v_to):
        for sl in range(t_start, t_end):
            if (a, sl) in sw:
                vp, ms = sw[(a, sl)]
                # Aircraft must be idle at vp during window
                # If the action overlaps the window, it's a conflict unless
                # the action is just being at vp (which flights/charges aren't)
                return False
        return True

    def check_reserve(s, v, slot, min_idle, min_soc):
        """Check if we can still meet reserve at (v, slot)."""
        count = 0
        for a in ac:
            if loc[a] == v and soc[a] >= min_soc - TOL:
                # Check if a is idle at this slot (not in any busy interval covering slot)
                idle = True
                for (bs, be) in busy[a]:
                    if bs <= slot < be:
                        idle = False
                        break
                if idle:
                    count += 1
        return count >= min_idle

    def can_depart(a, v, slot):
        """Check pad, noise, and service window for departure."""
        if (a, slot) in sw:
            return False
        if pad_use[(v, slot)] >= int(vertiports[v]["pad_count"]):
            return False
        period = slot_period(slot)
        quota = float(vertiports[v][f"departure_noise_quota_{period}"])
        return noise_use[(v, slot)] < quota  # will check after adding

    def try_flight(a, r, t):
        """Try to schedule request r on aircraft a departing at slot t. Returns True if success."""
        o, d = r["origin"], r["destination"]
        if not route_open(s, o, d):
            return False
        if loc[a] != o:
            return False
        dur = route_dur(s, o, d)
        t_end = t + dur
        if t_end > HORIZON:
            return False
        if not is_free(a, t, t_end):
            return False
        if not check_service_window(a, t, t_end, o, d):
            return False
        # Battery check
        energy = route_energy(s, o, d)
        if soc[a] - energy < RESERVE_SOC - TOL:
            return False
        # Pad at origin
        if pad_use[(o, t)] >= int(vertiports[o]["pad_count"]):
            return False
        # Pad at destination (arrival)
        if pad_use[(d, t_end - 1)] >= int(vertiports[d]["pad_count"]):
            return False
        # Noise
        noise = route_noise(s, o, d, a)
        period = slot_period(t)
        quota = float(vertiports[o][f"departure_noise_quota_{period}"])
        if noise_use[(o, t)] + noise > quota + TOL:
            return False
        # Corridor
        c = routes[(o, d)]["corridor_id"]
        for sl in range(t, t_end):
            if corridor_use[(c, sl)] >= corridor_cap(s, c, sl):
                return False
        # Commit
        pad_use[(o, t)] += 1
        pad_use[(d, t_end - 1)] += 1
        noise_use[(o, t)] += noise
        for sl in range(t, t_end):
            corridor_use[(c, sl)] += 1
        soc[a] -= energy
        loc[a] = d
        add_busy(a, t, t_end)
        return True

    def try_reposition(a, o, d, t):
        """Try to reposition aircraft a from o to d at slot t."""
        if loc[a] != o:
            return False
        if not route_open(s, o, d):
            return False
        dur = route_dur(s, o, d)
        t_end = t + dur
        if t_end > HORIZON:
            return False
        if not is_free(a, t, t_end):
            return False
        if not check_service_window(a, t, t_end, o, d):
            return False
        energy = route_energy(s, o, d)
        if soc[a] - energy < RESERVE_SOC - TOL:
            return False
        if pad_use[(o, t)] >= int(vertiports[o]["pad_count"]):
            return False
        if pad_use[(d, t_end - 1)] >= int(vertiports[d]["pad_count"]):
            return False
        noise = route_noise(s, o, d, a)
        period = slot_period(t)
        quota = float(vertiports[o][f"departure_noise_quota_{period}"])
        if noise_use[(o, t)] + noise > quota + TOL:
            return False
        c = routes[(o, d)]["corridor_id"]
        for sl in range(t, t_end):
            if corridor_use[(c, sl)] >= corridor_cap(s, c, sl):
                return False
        pad_use[(o, t)] += 1
        pad_use[(d, t_end - 1)] += 1
        noise_use[(o, t)] += noise
        for sl in range(t, t_end):
            corridor_use[(c, sl)] += 1
        soc[a] -= energy
        loc[a] = d
        add_busy(a, t, t_end)
        return True

    def try_charge(a, v, t, energy):
        """Try to charge aircraft a at v starting at slot t with given energy."""
        if loc[a] != v:
            return False
        cap = float(aircraft[a]["battery_capacity_kwh"])
        if soc[a] + energy > cap + TOL:
            energy = cap - soc[a]
            if energy < TOL:
                return False
        # Charger count
        if charger_use[(v, t)] >= int(vertiports[v]["charger_count"]):
            return False
        # Grid
        cd = float(scenarios[s]["charger_derate"])
        max_kw = float(aircraft[a]["max_charge_kw"]) * cd
        # Session duration: at least 1 slot
        dur = max(1, math.ceil(energy / max_kw))
        t_end = t + dur
        if t_end > HORIZON:
            return False
        if not is_free(a, t, t_end):
            return False
        if not check_service_window(a, t, t_end, v, v):
            return False
        # Grid check per slot
        for sl in range(t, t_end):
            gl = grid_limit(s, v, sl)
            # Power in this slot: energy distributed, but check total
            pass
        # Taper check: portion above high-SOC threshold
        high_soc = HIGH_SOC_FRAC * cap
        above = max(0, soc[a] + energy - high_soc)
        # Tapered allowance: TAPER_FRAC * max_kw * cd per slot
        tapered_allow = TAPER_FRAC * max_kw * dur
        if above > tapered_allow + TOL:
            # Reduce energy
            max_above = tapered_allow
            energy = max(0, high_soc + max_above - soc[a])
            if energy < TOL:
                return False
            dur = max(1, math.ceil(energy / max_kw))
            t_end = t + dur
            if t_end > HORIZON:
                return False
            if not is_free(a, t, t_end):
                return False
        # Grid power check
        for sl in range(t, t_end):
            gl = grid_limit(s, v, sl)
            slot_energy = energy / dur
            slot_power = slot_energy / (CFG["slot_minutes"] / 60.0)  # kW
            if grid_use[(v, sl)] + slot_power > gl + TOL:
                return False
        # Commit
        charger_use[(v, t)] += 1
        for sl in range(t, t_end):
            slot_energy = energy / dur
            slot_power = slot_energy / (CFG["slot_minutes"] / 60.0)
            grid_use[(v, sl)] += slot_power
        soc[a] += energy
        add_busy(a, t, t_end)
        return True

    # ── Greedy assignment ──
    # Sort requests by earliest slot, then by fare (descending)
    to_serve = sorted(accepted, key=lambda rid: (int(requests[rid]["earliest_slot"]), -float(requests[rid]["fare_per_passenger"])))
    served = {}  # rid -> (aircraft, start_slot, end_slot, energy)
    repositions = []  # (aircraft, o, d, t, t_end, energy)
    charges = []  # (aircraft, v, t, t_end, energy)

    # Pre-position: for each request, find aircraft that can reach origin in time
    # We'll try in order of earliest slot
    for rid in to_serve:
        r = requests[rid]
        o, d = r["origin"], r["destination"]
        e_slot = int(r["earliest_slot"])
        l_slot = int(r["latest_depart_slot"])
        placed = False
        for t in range(e_slot, l_slot + 1):
            if placed: break
            for a in ac:
                if placed: break
                # Can a reach o by slot t?
                if loc[a] == o:
                    if try_flight(a, r, t):
                        dur = route_dur(s, o, d)
                        served[rid] = (a, t, t + dur, route_energy(s, o, d))
                        placed = True
                else:
                    # Try to reposition a to o, then fly
                    # Find earliest slot a can depart for o
                    # a is at loc[a], needs to reach o
                    # Try repositioning from loc[a] to o
                    for rt in range(t - route_dur(s, loc[a], o) if loc[a] != o else t, t):
                        if rt < 0: continue
                        if not route_open(s, loc[a], o):
                            break
                        # Check if a is free at rt
                        if is_free(a, rt, rt + route_dur(s, loc[a], o)):
                            # Check service window
                            if check_service_window(a, rt, rt + route_dur(s, loc[a], o), loc[a], o):
                                # Try reposition
                                if try_reposition(a, loc[a], o, rt):
                                    # Now try flight
                                    if try_flight(a, r, t):
                                        dur = route_dur(s, o, d)
                                        served[rid] = (a, t, t + dur, route_energy(s, o, d))
                                        repositions.append((a, loc[a], o, rt, rt + route_dur(s, loc[a], o), route_energy(s, loc[a], o)))
                                        placed = True
                                        break
                        break  # only try earliest reposition
            # Try charging before flight if needed
            if not placed:
                for a in ac:
                    if loc[a] == o and soc[a] < route_energy(s, o, d) + RESERVE_SOC:
                        # Try charging
                        energy_needed = route_energy(s, o, d) + RESERVE_SOC - soc[a]
                        if try_charge(a, o, t - max(1, math.ceil(energy_needed / (float(aircraft[a]["max_charge_kw"]) * float(scenarios[s]["charger_derate"])))), energy_needed):
                            if try_flight(a, r, t):
                                dur = route_dur(s, o, d)
                                served[rid] = (a, t, t + dur, route_energy(s, o, d))
                                placed = True
                                break
        if not placed:
            # Try harder: reposition any aircraft
            for a in ac:
                if placed: break
                if loc[a] != o and route_open(s, loc[a], o):
                    rdur = route_dur(s, loc[a], o)
                    for rt in range(max(0, e_slot - rdur), e_slot):
                        if is_free(a, rt, rt + rdur) and check_service_window(a, rt, rt + rdur, loc[a], o):
                            if try_reposition(a, loc[a], o, rt):
                                for t in range(e_slot, l_slot + 1):
                                    if try_flight(a, r, t):
                                        dur = route_dur(s, o, d)
                                        served[rid] = (a, t, t + dur, route_energy(s, o, d))
                                        repositions.append((a, loc[a], o, rt, rt + rdur, route_energy(s, loc[a], o)))
                                        placed = True
                                        break
                        if placed: break
                        break
    return served, repositions, charges, loc, soc, busy

# ─── Main ────────────────────────────────────────────────────────────────────
def main():
    accepted, fs_model = solve_first_stage()
    if fs_model:
        fs_model.free()

    all_rows = []
    # Accept/decline rows
    for rid in requests:
        dec = "accept" if rid in accepted else "decline"
        all_rows.append(["accept", "", "", rid, "", "", "", "", "", "", dec])

    # Schedule each scenario
    for s in scenarios:
        served, repos, chgs, loc, soc, busy = schedule_scenario(s, accepted)
        for rid, (a, t, t_end, energy) in served.items():
            r = requests[rid]
            all_rows.append(["flight", s, a, rid, r["origin"], r["destination"], str(t), str(t_end), f"{energy:.8f}", r["passengers"], "serve"])
        for (a, o, d, t, t_end, energy) in repos:
            all_rows.append(["reposition", s, a, "", o, d, str(t), str(t_end), f"{energy:.8f}", "", "reposition"])
        for (a, v, t, t_end, energy) in chgs:
            all_rows.append(["charge", s, a, "", v, "", str(t), str(t_end), f"{energy:.8f}", "", "charge"])

    # Write solution
    out_path = "/app/submissions/solution.csv"
    os.makedirs("/app/submissions", exist_ok=True)
    with open(out_path, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["row_type","scenario_id","aircraft_id","request_id","origin","destination","start_slot","end_slot","energy_kwh","quantity","decision"])
        w.writerows(all_rows)
    print(f"Wrote {len(all_rows)} rows to {out_path}")

    # Validation
    print("=== Validation ===")
    # Check all accepted requests served in each scenario
    for s in scenarios:
        served_rids = set()
        for row in all_rows:
            if row[0] == "flight" and row[1] == s:
                served_rids.add(row[3])
        missing = accepted - served_rids
        if missing:
            print(f"WARNING: {s} missing {len(missing)} requests: {missing}")
        else:
            print(f"{s}: all {len(accepted)} accepted requests served")

if __name__ == "__main__":
    main()
